}

function snapToHexGrid(x, y) {
  // Facteur de hauteur d'un hexagone par rapport à sa largeur
  const heightFactor = Math.sqrt(3) / 2;

  // Largeur et hauteur d'un hexagone
  const hexWidth = hexRes * 2;
  const hexHeight = hexWidth * heightFactor;

  // Largeur d'une colonne (distance horizontale entre les centres)
  const colWidth = hexWidth * 0.75;

  // Identifier la colonne approximative
  let col = Math.round(x / colWidth);

  // Décalage de ligne pour les colonnes paires/impaires
  const isOddCol = col % 2 !== 0;
  const rowOffset = isOddCol ? hexHeight / 2 : 0;

  // Identifier la ligne
  let row = Math.round((y - rowOffset) / hexHeight);

  // Calculer les coordonnées finales du centre de l'hexagone
  const xSnapped = col * colWidth;
  const ySnapped = row * hexHeight + rowOffset;

  return { x: xSnapped, y: ySnapped };
}


// Fonction de mappage exponentiel

function mapExponential(value, inMin, inMax, outMin, outMax, exponent) {

  // Normaliser à [0, 1]

  const normalized = (value - inMin) / (inMax - inMin);



  // Appliquer l'exposant

  const exponential = Math.pow(normalized, exponent);



  // Mapper à la plage de sortie

  return exponential * (outMax - outMin) + outMin;

}

// Fonction de mappage logarithmique

function mapLogarithmic(value, inMin, inMax, outMin, outMax) {

  // Normaliser à [0, 1]

  var normalized = (value - inMin) / (inMax - inMin);



  // Éviter les valeurs négatives ou nulles pour le logarithme

  if (normalized <= 0) return outMin;



  // Appliquer la transformation logarithmique (base e)

  const logValue = Math.log(normalized) / Math.log(1);



  // Mapper à la plage de sortie

  return logValue * (outMax - outMin) + outMin;

}

// Version améliorée du mappage logarithmique avec base personnalisable

function mapLog(value, inMin, inMax, outMin, outMax, base = Math.E) {

  // Normaliser à [0, 1]

  var normalized = (value - inMin) / (inMax - inMin);



  // Éviter les valeurs négatives ou nulles

  if (normalized <= 0) return outMin;



  // Logarithme en base personnalisable

  var logValue = Math.log(normalized) / Math.log(base);



  // Mapper à la plage de sortie

  return (logValue + 1) * (outMax - outMin) + outMin;

}

// Fonction de mappage sinusoïdal

function mapSine(value, inMin, inMax, outMin, outMax) {

  // Normaliser à [0, 1]

  var normalized = (value - inMin) / (inMax - inMin);



  // Appliquer une transformation sinusoïdale (entre 0 et 1)

  const sine = Math.sin(normalized * Math.PI / 2);



  // Mapper à la plage de sortie

  return sine * (outMax - outMin) + outMin;

}

// Fonction de mappage avec courbe en S (sigmoïde)

function mapSigmoid(value, inMin, inMax, outMin, outMax, steepness = 10) {

  // Normaliser à [0, 1]

  var normalized = (value - inMin) / (inMax - inMin);



  // Centrer autour de 0 et ajuster la plage à [-6, 6] pour une bonne courbe sigmoïde

  const adjusted = (normalized - 0.5) * steepness;



  // Appliquer la fonction sigmoïde: 1 / (1 + e^(-x))

  const sigmoid = 1 / (1 + Math.exp(-adjusted));



  // Mapper à la plage de sortie

  return sigmoid * (outMax - outMin) + outMin;

}

// Fonction d'interpolation de Bézier cubique

function bezierInterpolation(t, p0, p1, p2, p3) {

  const cX = 3 * (p1.x - p0.x);

  const bX = 3 * (p2.x - p1.x) - cX;

  const aX = p3.x - p0.x - cX - bX;



  const cY = 3 * (p1.y - p0.y);

  const bY = 3 * (p2.y - p1.y) - cY;

  const aY = p3.y - p0.y - cY - bY;



  const x = (aX * Math.pow(t, 3)) + (bX * Math.pow(t, 2)) + (cX * t) + p0.x;

  const y = (aY * Math.pow(t, 3)) + (bY * Math.pow(t, 2)) + (cY * t) + p0.y;



  return { x, y };

}

// Fonction de mappage avec courbe de Bézier

function mapBezier(value, inMin, inMax, outMin, outMax, controlPoints) {

  // Normaliser à [0, 1]

  var normalized = (value - inMin) / (inMax - inMin);



  // Calculer le point sur la courbe de Bézier

  const bezierPoint = bezierInterpolation(

    normalized,

    { x: 0, y: 0 },

    controlPoints[0],

    controlPoints[1],

    { x: 1, y: 1 }

  );



  // Mapper à la plage de sortie en utilisant la valeur y du point de Bézier

  return bezierPoint.y * (outMax - outMin) + outMin;

}

// Fonction de mappage avec une fonction puissance (racine carrée, cubique, etc.)

function mapPower(value, inMin, inMax, outMin, outMax, power) {

  // Normaliser à [0, 1]

  var normalized = (value - inMin) / (inMax - inMin);



  // Appliquer la fonction puissance

  const powered = Math.pow(normalized, 1/power);



  // Mapper à la plage de sortie

  return powered * (outMax - outMin) + outMin;

}

// Fonction de mappage avec easing quadratique (accélération)

function mapEaseIn(value, inMin, inMax, outMin, outMax) {

  // Normaliser à [0, 1]

  var normalized = (value - inMin) / (inMax - inMin);



  // Accélération quadratique (t²)

  const eased = normalized * normalized;



  // Mapper à la plage de sortie

  return eased * (outMax - outMin) + outMin;

}

// Fonction de mappage avec easing quadratique (décélération)

function mapEaseOut(value, inMin, inMax, outMin, outMax) {

  // Normaliser à [0, 1]

  var normalized = (value - inMin) / (inMax - inMin);



  // Décélération quadratique (1-(1-t)²)

  var eased = 1 - Math.pow(1 - normalized, 2);



  // Mapper à la plage de sortie

  return eased * (outMax - outMin) + outMin;

}

